const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules',
  qs: {
    'filters[schedule_id]': 'SOME_STRING_VALUE',
    'filters[schedule_name]': 'SOME_STRING_VALUE',
    'filters[schedule_type]': 'SOME_STRING_VALUE',
    'filters[is_active]': 'SOME_BOOLEAN_VALUE',
    'filters[updated_at][gt]': 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/1234/projects/5678/schedules?filters%5Bschedule_id%5D=SOME_STRING_VALUE&filters%5Bschedule_name%5D=SOME_STRING_VALUE&filters%5Bschedule_type%5D=SOME_STRING_VALUE&filters%5Bis_active%5D=SOME_BOOLEAN_VALUE&filters%5Bupdated_at%5D%5Bgt%5D=SOME_STRING_VALUE&sort=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

